    if (typeof term === 'string') {
      const t = norm(term);
      if (!t) continue;
      const escaped = t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
      if (new RegExp('(^| )' + escaped + '( |$)').test(text)) total += 1;
    } else if (term.test(text)) total += 1;
  }
  return total;
}
